import {CATALOG,COSMETICS,COLORS,FINISHES,DEFAULT,PRESETS,SOURCES,VENDORS,CAPACITIES,bom,warnings,guide,selected,normalize,encode,decode,csv,isKit,hasBT,hasQi,hasTaptic} from './data.js';
let state=location.hash?decode(location.hash):normalize(DEFAULT),viewer=null,currentTab='configure';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const cap=n=>n>=1024?n/1024+'TB':n+'GB';
const choice=(key)=>`<div class="options" role="group" aria-label="${esc(key)}">${CATALOG[key].map(p=>`<button type="button" class="option ${state[key]===p.id?'selected':''}" data-key="${key}" data-value="${p.id}" aria-pressed="${state[key]===p.id}"><span class="radio"></span><span class="option-main"><span class="option-title">${esc(p.name)}</span><span class="option-desc">${esc(p.description)}</span><span class="option-meta"><span>Difficulty ${p.difficulty}/5</span><span>${esc(VENDORS[p.vendor].name)}</span></span></span><span class="price">${money(state.prices[key+':'+p.id]??p.price).replace('.00','')}</span></button>`).join('')}</div>`;
const swatches=(key,values,label)=>`<div class="field-label">${label}<span>${esc(values[state[key]].name)}</span></div><div class="swatches" role="group" aria-label="${label}">${Object.entries(values).map(([id,c])=>`<button class="swatch ${id==='transparent'?'clear':''}" style="--swatch:${c.hex}" data-key="${key}" data-value="${id}" title="${esc(c.name)}" aria-label="${label}: ${esc(c.name)}" aria-pressed="${state[key]===id}"></button>`).join('')}</div>`;
const group=(id,index,title,summary,body,open)=>`<details class="group" id="group-${id}" ${open?'open':''}><summary><span class="group-number">${String(index).padStart(2,'0')}</span><span class="group-name">${title}</span><span class="group-selection">${esc(summary)}</span></summary><div class="group-content">${body}</div></details>`;
function renderConfigure(){const open=new Set($$('.group[open]').map(x=>x.id));const first=!$('#configure-panel').children.length;
const g=(id,n,t,s,b)=>group(id,n,t,s,b,first?id==='front':open.has('group-'+id));
$('#configure-panel').innerHTML=[
 g('front',1,'Front plate',COLORS[state.front].name,swatches('front',COLORS,'Front color')+`<p class="hint">Replacement front · ${money(bom(state).find(r=>r.key==='front:'+state.front).price)} estimate · Difficulty ${COSMETICS.front.difficulty}/5<br>${VENDORS[COSMETICS.front.vendor].name}. ${COSMETICS.front.description}</p>`),
 g('back',2,'Back plate',state.connectivity==='moon'?'Classic Connect enclosure':(state.body==='thin'?'Thin':'Thick')+' · '+FINISHES[state.finish].name,choice('body')+'<h3 class="subhead">Finish</h3>'+swatches('finish',FINISHES,'Back finish')+(state.finish==='custom'?`<label class="custom-color">Custom finish <input type="color" data-input="customFinish" value="${state.customFinish}"></label>`:'')+'<p class="hint">Finish is included in the shell allowance. Kit color availability may differ. Polished and brushed finishes use different surface roughness.</p><h3 class="subhead">Port & back kits</h3>'+choice('connectivity')),
 g('wheel',3,'Click wheel',COLORS[state.wheel].name+' / '+COLORS[state.button].name,swatches('wheel',COLORS,'Wheel color')+swatches('button',COLORS,'Center button')+`<p class="hint">Wheel and button assembly · ${money(bom(state).find(r=>r.key==='wheel:'+state.wheel+':'+state.button).price)} estimate · Difficulty ${COSMETICS.wheel.difficulty}/5<br>${VENDORS[COSMETICS.wheel.vendor].name}. ${COSMETICS.wheel.description}</p>`),
 g('board',4,'Logic board',state.board==='7g'?'7th generation':state.board==='65g'?'6.5 generation':'Original 6th generation',choice('board')),
 g('storage',5,'Storage',selected(state,'storage').name+' · '+(state.storage==='hdd'?'80GB':cap(state.capacity)),choice('storage')+(state.storage!=='hdd'?'<h3 class="subhead">Total capacity</h3><div class="capacity" role="group" aria-label="Storage capacity">'+CAPACITIES.map(n=>`<button data-key="capacity" data-value="${n}" class="${state.capacity===n?'selected':''}" aria-pressed="${state.capacity===n}">${cap(n)}</button>`).join('')+'</div><p class="hint">Adapter and storage media are priced separately. Quad capacity is the total across one to four cards. Card capacity is advertised decimal capacity.</p>':'')),
 g('battery',6,'Battery',state.connectivity==='moon'?'Included in kit':selected(state,'battery').name,state.connectivity==='moon'?'<p class="hint">Classic Connect 2 includes its own battery. Your separate battery choice is retained for switching back, but excluded from this kit’s estimate.</p>':choice('battery')),
 g('screen',7,'Screen',state.screen==='keep'?'Keep original':'Stock replacement',choice('screen')),
 g('wireless',8,'Wireless',hasBT(state)?'Bluetooth'+(hasQi(state)?' + Qi':''):'Wired audio',isKit(state)?'<p class="hint">Bluetooth is included in your back kit. The original 3.5 mm audio jack remains usable. Confirm the selected kit’s codecs.</p>':'<h3 class="subhead">Bluetooth</h3>'+choice('bluetooth')),
 g('feel',9,'Feel & firmware',state.firmware==='rockbox'?'Rockbox':'Apple firmware','<h3 class="subhead">Firmware</h3>'+choice('firmware')+'<h3 class="subhead">Haptic feedback</h3>'+(state.connectivity==='moon'?'<p class="hint">Haptics are included in Classic Connect 2.</p>':choice('taptic'))+'<h3 class="subhead">Audio capacitor bypass</h3>'+choice('bypass')),
 g('cosmetic',10,'Engraving',state.engraving||'No engraving',`<label class="field-label" for="engraving">Back engraving <span>Optional · up to 80 characters</span></label><input class="text-field" id="engraving" data-input="engraving" maxlength="80" value="${esc(state.engraving)}" placeholder="A thousand songs. All yours."><p class="hint">${COSMETICS.engraving.description} Difficulty ${COSMETICS.engraving.difficulty}/5 when ordered engraved.</p><button class="quiet" data-view="back">View the back →</button>`)
].join('');
const wireless=$('#group-wireless .group-content');wireless.insertAdjacentHTML('beforeend','<h3 class="subhead">Wireless charging</h3>'+(state.connectivity==='moon'?'<p class="hint">Qi-compatible charging is included in Classic Connect 2.</p>':choice('qi'))+'<h3 class="subhead">Location tracking</h3>'+choice('airtag')+'<div class="blocked"><strong>Wi-Fi requires a different project</strong><p>There is no Wi-Fi add-on for the stock Classic logic board. A Raspberry Pi replacement replaces the core hardware and is incompatible with this configurator.</p><button disabled aria-describedby="wifi-note">Wi-Fi unavailable</button><span id="wifi-note" hidden>Requires full logic-board replacement with a computer.</span></div>');}
function renderParts(){const rows=bom(state);$('#parts-panel').innerHTML='<h3 class="panel-title">Your parts list</h3><p class="panel-copy">Change any price to match a quote or enter $0 for a part you already own. Edits are saved in your build link.</p><div class="export-actions"><button data-action="copy-bom">Copy as text</button><button data-action="csv">Download CSV</button></div>'+rows.map(r=>`<div class="bom-row"><div><strong>${esc(r.name)}</strong><a href="${r.url}" target="_blank" rel="noreferrer">${esc(r.vendor)} ↗</a></div><label class="bom-price">$<input type="number" min="0" max="100000" step="0.01" aria-label="Price: ${esc(r.name)}" data-price="${esc(r.key)}" value="${r.price}"></label></div>`).join('')+(state.connectivity==='moon'?'<p class="hint">Included in Classic Connect 2: enclosure, battery, Bluetooth, Qi receiver and haptics. These are charged once as a kit.</p>':'')+'<div class="breakdown"><h4 class="subhead">By category</h4>'+Object.entries(rows.reduce((a,r)=>(a[r.group]=(a[r.group]||0)+r.price,a),{})).map(([k,v])=>`<div class="subtotal"><span>${k}</span><span>${money(v)}</span></div>`).join('')+'</div><p class="hint">Donor iPod already owned. Tax, shipping, tools, labor and unpriced custom fabrication are not included. DIY electrical mods may require extra regulators, wiring and insulation.</p>';}
function renderGuide(){const steps=guide(state),minutes=steps.reduce((a,s)=>a+s.minutes,0),hours=minutes/60;$('#guide-panel').innerHTML=`<h3 class="panel-title">Your assembly plan</h3><p class="panel-copy">Allow roughly ${hours.toFixed(1)}–${(hours*1.5).toFixed(1)} hours for hands-on work, plus music transfer. Maximum difficulty ${Math.max(...steps.map(s=>s.difficulty))}/5.</p><p class="hint">1 = simple setup · 3 = delicate disassembly · 5 = advanced soldering / fabrication. Resolve fit warnings first. This is an order-of-work guide; follow detailed maker instructions.</p>`+steps.map((s,i)=>`<div class="step"><div class="step-num">${i+1}</div><div><h4>${s.name}</h4><p>${esc(s.detail)}</p><p class="step-meta">Difficulty ${s.difficulty}/5 · about ${s.minutes} min</p></div></div>`).join('');}
function renderWarnings(){const notes=warnings(state),n=notes.filter(n=>n.level==='warning').length;$('#compatibility').innerHTML=`<div class="compat-header">Compatibility check <span>${n?n+' to review':'No known conflicts'}</span></div>`+(notes.length?notes.map(r=>`<div class="notice ${r.level}"><strong>${esc(r.title)}</strong><p>${esc(r.message)}</p>${r.fix?`<button data-fix="${r.id}">Apply suggested fix →</button>`:''}</div>`).join(''):'<div class="compat-ok">No known conflicts for these selections. Confirm exact part dimensions with the vendor.</div>');$('#estimate-note').textContent=n?`${n} compatibility ${n===1?'warning':'warnings'} to review · estimates exclude tax & shipping.`:'Adjust prices in the parts list · excludes tax & shipping.';}
function renderSummary(){const rows=bom(state),total=rows.reduce((a,r)=>a+r.price,0);const p=money(total).split('.');$('#total').innerHTML=p[0]+'<span>.'+p[1]+'</span>';$('#part-count').textContent=rows.length;$('#model-summary').textContent=(state.storage==='hdd'?'80GB':cap(state.capacity))+' · '+(state.board==='7g'?'7th generation':state.board==='65g'?'6.5 generation':'6th generation')+' · '+(state.connectivity==='moon'?'Connect 2 body':state.body==='thin'?'Thin body':'Thick body');$('#finish-label').textContent=COLORS[state.front].name+' / '+FINISHES[state.finish].name;$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-pressed',String(b.dataset.view===state.view));});$('#xray').setAttribute('aria-pressed',state.xray);$('#inside-legend').hidden=!(state.xray||state.view==='exploded'||state.front==='transparent');$('#inside-legend').innerHTML=['Logic board',selected(state,'storage').name,state.connectivity==='moon'?'Kit battery':selected(state,'battery').name,hasBT(state)?'Bluetooth':null,hasQi(state)?'Qi coil':null,hasTaptic(state)?'Taptic motor':null,state.airtag==='on'?'AirTag':null].filter(Boolean).map(s=>`<span>${esc(s)}</span>`).join('');}
function applyTheme(){const dark=state.theme==='dark'||(state.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';$('#theme').title='Theme: '+state.theme;$('#theme').setAttribute('aria-label','Theme: '+state.theme+'. Click to change.');}
function save(){try{history.replaceState(null,'','#'+encode(state));}catch{}}
function render(){renderConfigure();renderParts();renderGuide();renderWarnings();renderSummary();applyTheme();}
function set(patch,{renderForm=true}={}){const old=state.view;state=normalize({...state,...patch});save();if(renderForm)render();else{renderParts();renderGuide();renderWarnings();renderSummary();}viewer?.update(state);if(old!==state.view)viewer?.angle(state.view);}
function tab(name,scroll=false){currentTab=name;$$('[data-tab]').forEach(b=>{const active=b.dataset.tab===name;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;});for(const id of ['configure','parts','guide'])$('#'+id+'-panel').hidden=id!==name;if(scroll) $('.tabs').scrollIntoView({behavior:'smooth',block:'start'});}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
async function copy(text,title){try{await navigator.clipboard.writeText(text);toast(title+' copied');}catch{$('#copy-title').textContent=title;$('#copy-text').value=text;$('#copy-dialog').showModal();$('#copy-text').select();}}
function exportBOM(){return 'CLASSIC STUDIO — PARTS LIST\n\n'+bom(state).map(r=>`${r.group} | ${r.name} | ${r.vendor} | ${money(r.price)} | ${r.url}`).join('\n')+'\n\nEstimated total: '+money(bom(state).reduce((a,r)=>a+r.price,0))+'\nExcludes tax, shipping, tools and labor.\n\nCOMPATIBILITY\n'+warnings(state).map(r=>r.title+': '+r.message).join('\n');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.key){set({[b.dataset.key]:b.dataset.key==='capacity'?Number(b.dataset.value):b.dataset.value});$('#preset').value='';}if(b.dataset.view)set({view:b.dataset.view});if(b.dataset.tab)tab(b.dataset.tab);if(b.dataset.fix){const r=warnings(state).find(r=>r.id===b.dataset.fix);if(r?.fix){set(r.fix);toast('Suggested fix applied');}}if(b.dataset.action==='copy-bom')copy(exportBOM(),'Parts list');if(b.dataset.action==='csv'){const blob=new Blob([csv(bom(state))],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='classic-studio-parts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Parts CSV downloaded');}});
function commitPrice(input){const value=input.value;const price=Number(value);if(value===''||!Number.isFinite(price)||price<0||price>100000){input.setCustomValidity('Enter a price from $0 to $100,000.');return;}input.setCustomValidity('');state=normalize({...state,prices:{...state.prices,[input.dataset.price]:price}});save();renderSummary();renderConfigure();const totals=Object.entries(bom(state).reduce((a,r)=>(a[r.group]=(a[r.group]||0)+r.price,a),{}));$('#parts-panel .breakdown').innerHTML='<h4 class="subhead">By category</h4>'+totals.map(([k,v])=>`<div class="subtotal"><span>${k}</span><span>${money(v)}</span></div>`).join('');}
document.addEventListener('input',e=>{if(e.target.dataset.price)commitPrice(e.target);if(e.target.dataset.input){set({[e.target.dataset.input]:e.target.value},{renderForm:false});if(e.target.dataset.input==='engraving')$('#group-cosmetic .group-selection').textContent=e.target.value||'No engraving';}});
document.addEventListener('change',e=>{if(e.target.dataset.price){commitPrice(e.target);if(!e.target.validity.valid)e.target.reportValidity();}});
$('#preset').addEventListener('change',e=>{if(PRESETS[e.target.value]){const name=e.target.value;set({...PRESETS[name],prices:{},theme:state.theme});$('#preset').value=name;toast('Preset applied');}});
$('#reset').addEventListener('click',()=>{set({...DEFAULT,prices:{},theme:state.theme});$('#preset').value='';toast('Build reset');});$('#share').addEventListener('click',()=>{save();copy(location.href,'Build link');});$('#xray').addEventListener('click',()=>set({xray:!state.xray}));$('#review-parts').addEventListener('click',()=>tab(currentTab==='parts'?'configure':'parts',true));$('#theme').addEventListener('click',()=>{const themes=['system','light','dark'];set({theme:themes[(themes.indexOf(state.theme)+1)%3]});toast('Theme: '+state.theme);});$('#close-copy').addEventListener('click',()=>$('#copy-dialog').close());
$('.brand').addEventListener('click',e=>{e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});});
$('.tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=['configure','parts','guide'];const i=e.key==='Home'?0:e.key==='End'?2:(tabs.indexOf(currentTab)+(e.key==='ArrowRight'?1:2))%3;tab(tabs[i]);$('#tab-'+tabs[i]).focus();});
window.addEventListener('hashchange',()=>{const old=state.view;state=decode(location.hash);render();viewer?.update(state);if(old!==state.view)viewer?.angle(state.view);$('#preset').value='';toast('Build restored from link');});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
$('#sources-list').innerHTML=SOURCES.map(([n,url])=>`<a href="${url}" target="_blank" rel="noreferrer">${n} ↗</a>`).join('');render();tab('configure');
// WebMCP uses the same state reducer as the form, with strict field validation.
const context=document.modelContext;const lifecycle=new AbortController();if(context?.registerTool){const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'read_ipod_build',title:'Read iPod build',description:'Read the current iPod configuration, estimated parts and compatibility warnings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({configuration:state,parts:bom(state),warnings:warnings(state),total:bom(state).reduce((a,r)=>a+r.price,0)})});
register({name:'configure_ipod_build',title:'Configure iPod build',description:'Change selected options in the visible iPod configurator. Wi-Fi is unavailable.',inputSchema:{type:'object',properties:{changes:{type:'object',properties:Object.fromEntries([...Object.entries(CATALOG).map(([k,v])=>[k,{type:'string',enum:v.map(x=>x.id)}]),['capacity',{type:'number',enum:CAPACITIES}],...['front','wheel','button'].map(k=>[k,{type:'string',enum:Object.keys(COLORS)}]),['finish',{type:'string',enum:Object.keys(FINISHES)}],['engraving',{type:'string',maxLength:80}]]),additionalProperties:false}},required:['changes'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input?.changes||typeof input.changes!=='object'||Array.isArray(input.changes))throw new Error('changes must be an object');const permitted=new Set([...Object.keys(CATALOG),'capacity','front','wheel','button','finish','engraving']);const candidate=normalize({...state,...input.changes});for(const [k,v] of Object.entries(input.changes)){if(!permitted.has(k)||candidate[k]!==v)throw new Error('Invalid option: '+k);}set(input.changes);return {configuration:state,total:bom(state).reduce((a,r)=>a+r.price,0),warnings:warnings(state)};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
async function loadViewer(){try{const {createViewer}=await import('./viewer.js');viewer=await createViewer($('#viewer'),state);$('#viewer-status')?.remove();window.__viewerReady=true;}catch(error){if(!$('#viewer-status'))$('#viewer').insertAdjacentHTML('beforeend','<div id="viewer-status"></div>');$('#viewer-status').innerHTML='The 3D preview could not load. Check your connection and WebGL support.<button id="retry-viewer">Retry preview</button>';$('#retry-viewer').onclick=()=>location.reload();console.error('Viewer error:',error);}}
loadViewer();
